import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  return (
    <div className="bg-gray-800 text-white min-h-screen">
      <header className="flex justify-between items-center p-4">
          <nav className="space-x-4 bg-red-500 p-4 rounded-md">
      <img src="logo.png" width="64" alt="Logo" />
      <Link to="/" className="hover:text-gray-400 text-white">Home</Link>
      <Link to="/about" className="hover:text-gray-400 text-white">About</Link>
      <Link to="/photography" className="hover:text-gray-400 text-white">Photography</Link>
      <Link to="/portfolio" className="hover:text-gray-400 text-white">Portfolio</Link>
    </nav>


      </header>

      <main className="p-8">
        <h1>Welcome to my homepage</h1>
        <p>This is a simple page using React and Tailwind CSS.</p>
      </main>
    </div>
  );
};

export default Home;
